import { Category, ServiceCatalog, Specialty, SubSpecialty } from '@/types/category.types';
import {
  Timestamp,
  collection,
  doc,
  getDoc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  setDoc,
  updateDoc,
  where,
} from 'firebase/firestore';
import { db } from './config';

// ============================================
// FUNCIONES AUXILIARES
// ============================================
const getDb = () => {
  if (!db) throw new Error('Firestore no está disponible');
  return db;
};

// ============================================
// 1️⃣ CATEGORÍAS
// ============================================
export const getAllCategories = async (): Promise<Category[]> => {
  try {
    const dbInstance = getDb();
    const q = query(
      collection(dbInstance, 'categories'),
      where('isActive', '==', true),
      orderBy('order', 'asc')
    );
    const snapshot = await getDocs(q);
    const categories: Category[] = [];
    snapshot.forEach((doc) => {
      categories.push({ id: doc.id, ...doc.data() } as Category);
    });
    return categories;
  } catch (error) {
    console.error('Error obteniendo categorías:', error);
    return [];
  }
};

export const getCategoryById = async (categoryId: string): Promise<Category | null> => {
  try {
    const dbInstance = getDb();
    const docRef = doc(dbInstance, 'categories', categoryId);
    const snapshot = await getDoc(docRef);
    if (snapshot.exists()) {
      return { id: snapshot.id, ...snapshot.data() } as Category;
    }
    return null;
  } catch (error) {
    console.error('Error obteniendo categoría:', error);
    return null;
  }
};

