// ============================================
// 4️⃣ CATÁLOGO COMPLETO (PARA CACHÉ)
// ============================================
export const getFullCatalog = async (): Promise<ServiceCatalog> => {
  try {
    const dbInstance = getDb();

    // Obtener todo en paralelo
    const [categories, specialties, subSpecialties] = await Promise.all([
      getAllCategories(),
      getAllSpecialties(),
      // Obtener todas las subespecialidades (limitado)
      getSubSpecialtiesBySpecialty('all'), // Necesitarías ajustar esto
    ]);

    return {
      categories,
      specialties,
      subSpecialties,
      lastUpdated: Timestamp.now(),
      version: '1.0.0',
    };
  } catch (error) {
    console.error('Error obteniendo catálogo completo:', error);
    return {
      categories: [],
      specialties: [],
      subSpecialties: [],
      lastUpdated: Timestamp.now(),
      version: '1.0.0',
    };
  }
};

// ============================================
// 5️⃣ ADMIN: GESTIÓN DE CATÁLOGO
// ============================================
export const createCategory = async (
  data: Omit<Category, 'id' | 'createdAt' | 'updatedAt'>
): Promise<string> => {
  try {
    const dbInstance = getDb();
    const docRef = doc(collection(dbInstance, 'categories'));
    const now = serverTimestamp();

    await setDoc(docRef, {
      ...data,
      createdAt: now,
      updatedAt: now,
    });

    return docRef.id;
  } catch (error) {
    console.error('Error creando categoría:', error);
    throw new Error('Error al crear la categoría');
  }
};

export const updateCategory = async (
  categoryId: string,
  data: Partial<Category>
): Promise<void> => {
  try {
    const dbInstance = getDb();
    const docRef = doc(dbInstance, 'categories', categoryId);
    await updateDoc(docRef, {
      ...data,
      updatedAt: serverTimestamp(),
    });
  } catch (error) {
    console.error('Error actualizando categoría:', error);
    throw new Error('Error al actualizar la categoría');
  }
};

// ============================================
// 6️⃣ OBTENER ESPECIALIDADES DE UN PROVEEDOR
// ============================================
export const getProviderSpecialties = async (providerId: string): Promise<ProviderSpecialty[]> => {
  try {
    const dbInstance = getDb();
    const docRef = doc(dbInstance, 'providers', providerId);
    const snapshot = await getDoc(docRef);

    if (snapshot.exists()) {
      const data = snapshot.data();
      const specialtyIds = data.specialties || [];

      // Obtener detalles de cada especialidad
      const specialties: ProviderSpecialty[] = [];
      for (const id of specialtyIds) {
        const specialty = await getSpecialtyById(id);
        if (specialty) {
          const category = await getCategoryById(specialty.categoryId);
          specialties.push({
            specialtyId: specialty.id,
            name: specialty.name,
            categoryId: specialty.categoryId,
            categoryName: category?.name || 'Sin categoría',
            experience: data.experience || 0,
            rate: data.rate,
            isVerified: data.isVerified || false,
            certifications: data.certifications || [],
            portfolioIds: data.portfolioIds || [],
          });
        }
      }
      return specialties;
    }
    return [];
  } catch (error) {
    console.error('Error obteniendo especialidades del proveedor:', error);
    return [];
  }
};

// ============================================
// 7️⃣ BUSCAR PROFESIONALES POR ESPECIALIDAD
// ============================================
export const searchProvidersBySpecialty = async (
  specialtyId: string,
  location?: string
): Promise<ProviderWithSpecialties[]> => {
  try {
    const dbInstance = getDb();
    const q = query(
      collection(dbInstance, 'providers'),
      where('specialties', 'array-contains', specialtyId),
      where('isActive', '==', true)
    );

    const snapshot = await getDocs(q);
    const providers: ProviderWithSpecialties[] = [];

    for (const doc of snapshot.docs) {
      const data = doc.data();
      const providerSpecialties = await getProviderSpecialties(doc.id);

      // Filtrar por ubicación si se especifica
      if (location && data.location !== location) continue;

      providers.push({
        uid: doc.id,
        displayName: data.displayName,
        email: data.email,
        phone: data.phone,
        photoURL: data.photoURL,
        location: data.location,
        specialties: providerSpecialties,
        categories: data.categories || [],
        rating: data.rating || 0,
        totalRatings: data.totalRatings || 0,
        isActive: data.isActive,
        createdAt: data.createdAt,
        updatedAt: data.updatedAt,
      });
    }

    return providers;
  } catch (error) {
    console.error('Error buscando proveedores:', error);
    return [];
  }
};
